    def build(vals):
        # insert in order, return level order string
        V = []; L = []; R = []
        for v in vals:
            V.append(v); L.append(-1); R.append(-1)
            k = len(V) - 1
            if k == 0:
                continue
            u = 0
            while True:
                if v < V[u]:
                    if L[u] == -1:
                        L[u] = k; break
                    u = L[u]
                else:
                    if R[u] == -1:
                        R[u] = k; break
                    u = R[u]
        out = []
        queue = [0]
        qi = 0
        while qi < len(queue):
            u = queue[qi]; qi += 1
            if u == -1:
                out.append('null')
                continue
            out.append(str(V[u]))
            queue.append(L[u])
            queue.append(R[u])
        while out and out[-1] == 'null':
            out.pop()
        return ' '.join(out)
